/**
 * How Paulownia, seven-five-seven (`goshichi-no-kiri`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/goshichi-no-kiri";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"The same plan as the five-three paulownia with more and smaller florets: seven in the middle spike and five in each of the others. The top floret is bitten twice into three points. The spikes are as tall as the five-three paulownia's. The left half is struck first and the right half is struck in place as its mirror.","ja":"五三桐と同じ構図で、花を小さくして数を増やし、中央の花穂に七つ、左右の花穂に五つずつつけます。いちばん上の花は、上の縁を二か所切り取り、三つの山にします。花穂の高さは五三桐と同じです。左半分を先に作図し、右半分はその場で左右対称に作図します。"};

export default construction;
export { construction, description };
